// ori x7,x7,64\n            10'h108 : o_inst = 32'h0041d463; // bge x3,x4,110 <_start+0x110>\n            10'h10c : o_inst = 32'h0803e393; // ori x7,x7,128\n            10'h110 : o_inst = 32'h00425463; // bge x4,x4,118 <_start+0x118>\n            10'h114 : o_inst = 32'h1003e393; // ori x7,x7,256\n            10'h118 : o_inst = 32'h00326463; // bltu x4,x3,120 <_start+0x120>\n            10'h11c : o_inst = 32'h00146413; // ori x8,x8,1\n            10'h120 : o_inst = 32'h0041e463; // bltu x3,x4,128 <_start+0x128>\n            10'h124 : o_inst = 32'h00246413; // ori x8,x8,2\n            10'h128 : o_inst = 32'h0041f463; // bgeu x3,x4,130 <_start+0x130>\n            10'h12c : o_inst = 32'h00446413; // ori x8,x8,4\n            10'h130 : o_inst = 32'h00327463; // bgeu x4,x3,138 <_start+0x138>\n            10'h134 : o_inst = 32'h00846413; // ori x8,x8,8\n            10'h138 : o_inst = 32'h00427463; // bgeu x4,x4,140 <_start+0x140>\n            10'h13c : o_inst = 32'h01046413; // ori x8,x8,16\n            10'h140 : o_inst = 32'h047fac23; // sw x7,88(x31)\n            10'h144 : o_inst = 32'h048fae23; // sw x8,92(x31)\n            10'h148 : o_inst = 32'h00000493; // addi x9,x0,0\n            10'h14c : o_inst = 32'h00500513; // addi x10,x0,5\n            10'h150 : o_inst = 32'h00a484b3; // add x9,x9,x10\n            10'h154 : o_inst = 32'hfff50513; // addi x10,x10,-1\n            10'h158 : o_inst = 32'hfe051ce3; // bne x10,x0,150 <_start+0x150>\n            10'h15c : o_inst = 32'h069fa023; // sw x9,96(x31)\n            10'h160 : o_inst = 32'h00000393; // addi x7,x0,0\n            10'h164 : o_inst = 32'h008005ef; // jal x11,16c <_start+0x16c>\n            10'h168 : o_inst = 32'h0013e393; // ori x7,x7,1\n            10'h16c : o_inst = 32'h00000617; // auipc x12,0x0\n            10'h170 : o_inst = 32'h011606e7; // jalr x13,17(x12)\n            10'h174 : o_inst = 32'h0023e393; // ori x7,x7,2\n            10'h178 : o_inst = 32'h0043e393; // ori x7,x7,4\n            10'h17c : o_inst = 32'h40c68733; // sub x14,x13,x12\n            10'h180 : o_inst = 32'h40c587b3; // sub x15,x11,x12\n            10'h184 : o_inst = 32'h067fa223; // sw x7,100(x31)\n            10'h188 : o_inst = 32'h06efa423; // sw x14,104(x31)\n            10'h18c : o_inst = 32'h06ffa623; // sw x15,108(x31)\n            10'h190 : o_inst = 32'h0c1fa023; // sw x1,192(x31)\n            10'h194 : o_inst = 32'h0c3fa223; // sw x3,196(x31)\n            10'h198 : o_inst = 32'h0c0f8283; // lb x5,192(x31)\n            10'h19c : o_inst = 32'h065fa823; // sw x5,112(x31)\n            10'h1a0 : o_inst = 32'h0c3f8283; // lb x5,195(x31)\n            10'h1a4 : o_inst = 32'h065faa23; // sw x5,116(x31)\n            10'h1a8 : o_inst = 32'h0c4f8283; // lb x5,196(x31)\n            10'h1ac : o_inst = 32'h065fac23; // sw x5,120(x31)\n            10'h1b0 : o_inst = 32'h0c4fc283; // lbu x5,196(x31)\n            10'h1b4 : o_inst = 32'h065fae23; // sw x5,124(x31)\n            10'h1b8 : o_inst = 32'h0c2f9283; // lh x5,194(x31)\n            10'h1bc : o_inst = 32'h085fa023; // sw x5,128(x31)\n            10'h1c0 : o_inst = 32'h0c4f9283; // lh x5,196(x31)\n            10'h1c4 : o_inst = 32'h085fa223; // sw x5,132(x31)\n            10'h1c8 : o_inst = 32'h0c6fd283; // lhu x5,198(x31)\n            10'h1cc : o_inst = 32'h085fa423; // sw x5,136(x31)\n            10'h1d0 : o_inst = 32'h0c0fd283; // lhu x5,192(x31)\n            10'h1d4 : o_inst = 32'h085fa623; // sw x5,140(x31)\n            10'h1d8 : o_inst = 32'h0c4f80a3; // sb x4,193(x31)\n            10'h1dc : o_inst = 32'h0c3f8123; // sb x3,194(x31)\n            10'h1e0 : o_inst = 32'h0c4f9323; // sh x4,198(x31)\n            10'h1e4 : o_inst = 32'h0c0fa283; // lw x5,192(x31)\n            10'h1e8 : o_inst = 32'h085fa823; // sw x5,144(x31)\n            10'h1ec : o_inst = 32'h0c4fa283; // lw x5,196(x31)\n            10'h1f0 : o_inst = 32'h085faa23; // sw x5,148(x31)\n            10'h1f4 : o_inst = 32'h0c0fa423; // sw x0,200(x31)\n            10'h1f8 : o_inst = 32'h0c1f9423; // sh x1,200(x31)\n            10'h1fc : o_inst = 32'h0c1f9523; // sh x1,202(x31)\n            10'h200 : o_inst = 32'h0c8fa283; // lw x5,200(x31)\n            10'h204 : o_inst = 32'h085fac23; // sw x5,152(x31)\n            10'h208 : o_inst = 32'h00500013; // addi x0,x0,5\n            10'h20c : o_inst = 32'h080fae23; // sw x0,156(x31)\n            10'h210 : o_inst = 32'h00100293; // addi x5,x0,1\n            10'h214 : o_inst = 32'h0a5fae23; // sw x5,188(x31)\n            10'h218 : o_inst = 32'h0000006f; // jal x0,218 <halt>\n            default: o_inst = 32'h00000013; // nop\n        }\n    }\n}\n"}],"same_hw":"c_hello","asic":false,"title_en":"C: music on the buzzer","note_en":"square waves on PMOD1A pin 1 (the buzzer module): Twinkle, Twinkle","group_en":"C programs"},{"id":"c_switches","group":"C 程式","title":"C：開關","note":"PMOD1B 的 8 個開關顯示在 PMOD1A 的 8 顆 LED，並在終端機印出二進位 / 十六進位","synth":"RvBoard","pcf":"# RvBoard (examples/src/rvsoc.veryl) on an iCEBreaker: BTN_N resets, BTN1-3, the USB serial port,\n# 8 outputs on PMOD1A (the 8-LED module, a 7-segment display, ...), 8 inputs on PMOD1B (the switch module)\nset_io -nowarn i_clk    35\nset_io -nowarn i_rst    10\nset_io -nowarn i_btn[0] 20\nset_io -nowarn i_btn[1] 19\nset_io -nowarn i_btn[2] 18\nset_io -nowarn i_rx     6\nset_io -nowarn o_tx     9\nset_io -nowarn o_led[0] 4\nset_io -nowarn o_led[1] 2\nset_io -nowarn o_led[2] 47\nset_io -nowarn o_led[3] 45\nset_io -nowarn o_led[4] 3\nset_io -nowarn o_led[5] 48\nset_io -nowarn o_led[6] 46\nset_io -nowarn o_led[7] 44\nset_io -nowarn i_sw[0] 43\nset_io -nowarn i_sw[1] 38\nset_io -nowarn i_sw[2] 34\nset_io -nowarn i_sw[3] 31\nset_io -nowarn i_sw[4] 42\nset_io -nowarn i_sw[5] 36\nset_io -nowarn i_sw[6] 32\nset_io -nowarn i_sw[7] 28\n","board":{"baud":115200,"mode":"cpu","uart":true,"pmod1a":"led8","pmod1b":"sw8"},"files":[{"name":"switches.c","src":"// C 實驗 6：開關 —— PMOD1B 的 8 個開關（SWITCHES）顯示在 PMOD1A 的 8 顆 LED，\n// 開關一變就在終端機印出它的二進位、十六進位和十進位\n\nint main(void) {\n    unsigned last = 256;\n    while (1) {\n        unsigned s = SWITCHES;\n        LED = s;\n        if (s != last) {\n            int i;\n            printf(\"switches \");\n            for (i = 7; i >= 0; i--) putchar(s & (1 << i) ? '1' : '0');\n            printf(\" = 0x%02x = %d\\n\", s, s);\n            last = s;\n        }\n    }\n}\n"},{"name":"rvsoc.veryl","src":"// ==========================================\n// 多週期 RISC-V SoC：程式、資料與暫存器檔都放在 block RAM\n// ==========================================\n// 單週期的 RiscvCore（rv32i.veryl）把 32 個暫存器做成正反器，完整版需要\n// 5,400 個 LUT，放不進 iCE40UP5K。這裡的 RvCore 改成多週期：\n//   Fetch  → 送出 pc 的讀取位址（只在重設後與 load 之後）\n//   Decode → 記憶體讀出指令，同一拍用它的 rs1 / rs2 讀暫存器檔\n//   Exec   → 運算、寫回、算下一個 pc 並且立刻送出它的讀取位址（store 同時寫入）\n//   Mem    → load：記憶體讀出資料，寫回，送出 pc 的讀取位址\n// 一般指令 2 拍、load 3 拍。暫存器檔與記憶體都是同步讀取（下一拍才有資料），\n// RV32IMA + Zicsr：乘除法（反覆式，35 拍）、原子指令（LR / SC、AMO 3 拍）、\n// machine mode 的陷阱（中斷、ecall、ebreak、非法指令、位址沒對齊；陷入多 1 拍）、mret、wfi；\n// 這些足夠跑搶佔式的多執行緒作業系統（計時器中斷切換執行緒）。\n// 合成到 FPGA 時變成 SB_RAM40_4K。需要 rv32i.veryl（RiscvTypes、Alu）、\n// sync_ram.veryl（SyncRam）與 uart.veryl（UartTx、UartRx）。\n//\n// 記憶體映射（位址 bit 28 = 1 是周邊）：\n//   0x0000_0000  8 KB RAM（程式與資料，RvSoc 的 MEM_AW 決定大小）\n//   0x1000_0000  LED      讀寫，8 bit\n//   0x1000_0004  BTN      讀：bit 2..0 = BTN3..BTN1，bit 15..8 = PMOD1B 的 8 個開關\n//   0x1000_0008  UART     寫：送出一個位元組；讀：收到的位元組（讀了就清掉 RXV）\n//   0x1000_000C  UART_ST  讀：bit 0 = TX 忙碌，bit 1 = RXV（有收到的位元組）\n//   0x1000_0010  MTIME    讀寫：重設後經過的時脈數（32 bit，12 MHz 下約 357 秒繞一圈；0x14 高位元讀 0）\n//   0x1000_0018  MTIMECMP 讀寫：mtime ≥ mtimecmp 時計時器中斷（重設後是全 1；0x1C 高位元讀 0）\n//   0x1000_0020  MSIP     讀寫：bit 0 = 軟體中斷\n//   中斷：計時器 → mip.MTIP，MSIP → mip.MSIP，UART 收到位元組（RXV）→ mip.MEIP\n//   0x1000_2000 以上     寫到外部匯流排 o_x*（例如 VgaText：0x1000_2000 字元、0x1000_4000 字型、0x1000_6000 顏色）\n\nmodule RvCore (\n    i_clk      : input  clock    ,\n    i_rst      : input  reset    ,\n    i_run      : input  logic    , // 0：停在 pc = 0（載入程式時）\n    o_raddr    : output logic<32>, // 讀取位址（取指令或 load），下一拍 i_rdata 才有資料\n    o_re       : output logic    ,\n    i_rdata    : input  logic<32>,\n    o_waddr    : output logic<32>, // 寫入位址（store）\n    o_wstrb    : output logic<4> , // 要寫的位元組；0 = 不寫\n    o_wdata    : output logic<32>,\n    i_irq_timer: input  logic    , // mtime ≥ mtimecmp（mip.MTIP）\n    i_irq_soft : input  logic    , // msip（mip.MSIP）\n    i_irq_ext  : input  logic    , // 外部（UART 收到位元組，mip.MEIP）\n    i_mtime    : input  logic<64>, // time CSR\n) {\n    import RiscvTypes::*;\n\n    const FETCH : logic<3> = 3'd0;\n    const DECODE: logic<3> = 3'd1;\n    const EXEC  : logic<3> = 3'd2;\n    const MEM   : logic<3> = 3'd3;\n    const MULDIV: logic<3> = 3'd4;\n    const WFI   : logic<3> = 3'd5;\n\n    var state : logic<3> ;\n    var pc    : logic<32>;\n    var ir    : logic<32>; // 執行中的指令\n    var lsaddr: logic<32>; // load / AMO 的位址（Mem 用）\n\n    // Decode 那一拍指令還在 i_rdata 上，之後在 ir\n    let cur: logic<32> = if state == DECODE ? i_rdata : ir;\n\n    let opcode : logic<7> = ir[6:0];\n    let rd_idx : logic<5> = ir[11:7];\n    let funct3 : logic<3> = ir[14:12];\n    let rs1_idx: logic<5> = ir[19:15];\n    let funct7 : logic<7> = ir[31:25];\n    let funct5 : logic<5> = ir[31:27];\n\n    // --- 暫存器檔：兩份相同的同步讀取 RAM（兩個讀取埠），一起寫入 ---\n    var rf_we  : logic    ;\n    var rf_wd  : logic<32>;\n    var rs1_raw: logic<32>;\n    var rs2_raw: logic<32>;\n\n    inst u_rf1: SyncRam #(ADDR_W: 5, DATA_W: 32) (\n        i_clk  : i_clk      ,\n        i_we   : rf_we      ,\n        i_waddr: rd_idx     ,\n        i_wdata: rf_wd      ,\n        i_re   : 1'b1       ,\n        i_raddr: cur[19:15] ,\n        o_rdata: rs1_raw    ,\n    );\n    inst u_rf2: SyncRam #(ADDR_W: 5, DATA_W: 32) (\n        i_clk  : i_clk      ,\n        i_we   : rf_we      ,\n        i_waddr: rd_idx     ,\n        i_wdata: rf_wd      ,\n        i_re   : 1'b1       ,\n        i_raddr: cur[24:20] ,\n        o_rdata: rs2_raw    ,\n    );\n\n    // x0 永遠是 0（RAM 裡的 x0 從來不寫，但模擬時一開始是 x）；是不是 x0 在 Decode 就先判斷\n    var rs1_zero: logic;\n    var rs2_zero: logic;\n    let rs1_data: logic<32> = if rs1_zero ? 32'd0 : rs1_raw;\n    let rs2_data: logic<32> = if rs2_zero ? 32'd0 : rs2_raw;\n\n    // --- 指令分類 ---\n    let op_load  : logic = opcode == Opcode::Load;\n    let op_store : logic = opcode == Opcode::Store;\n    let op_system: logic = opcode == 7'b1110011;\n    let op_amo   : logic = opcode == 7'b0101111;\n    let muldiv   : logic = opcode == Opcode::RType && funct7 == 7'b0000001;\n    let is_lr    : logic = op_amo && funct5 == 5'b00010;\n    let is_sc    : logic = op_amo && funct5 == 5'b00011;\n    let is_amo   : logic = op_amo && !is_lr && !is_sc; // 讀、改、寫\n    let is_ecall : logic = ir == 32'h0000_0073;\n    let is_ebreak: logic = ir == 32'h0010_0073;\n    let is_mret  : logic = ir == 32'h3020_0073;\n    let is_wfi   : logic = ir == 32'h1050_0073;\n    let is_csr   : logic = op_system && funct3 != 3'd0 && funct3 != 3'd4;\n\n    // --- 立即數：Decode 那一拍從讀出的指令解出來，存進 imm（Exec 不用再解碼）---\n    let c_op : logic<7> = cur[6:0];\n    var imm_d: logic<32>;\n    always_comb {\n        case c_op {\n            Opcode::IType, Opcode::Load, Opcode::Jalr:\n                imm_d = {cur[31] repeat 20, cur[31:20]};\n            Opcode::Store:\n                imm_d = {cur[31] repeat 20, cur[31:25], cur[11:7]};\n            Opcode::Branch:\n                imm_d = {cur[31] repeat 20, cur[7], cur[30:25], cur[11:8], 1'b0};\n            Opcode::Jal:\n                imm_d = {cur[31] repeat 12, cur[19:12], cur[20], cur[30:21], 1'b0};\n            Opcode::Lui, Opcode::Auipc:\n                imm_d = {cur[31:12], 12'd0};\n            default:\n                imm_d = 32'd0; // AMO / LR / SC：位址就是 rs1\n        }\n    }\n    var imm: logic<32>;\n\n    // --- ALU 運算 ---\n    let alt: logic = funct7[5] && (opcode == Opcode::RType || funct3 == 3'b101);\n    var alu_op: AluOp;\n    always_comb {\n        if opcode == Opcode::RType || opcode == Opcode::IType {\n            case funct3 {\n                3'b000 : alu_op = if alt ? AluOp::Sub : AluOp::Add;\n                3'b001 : alu_op = AluOp::Sll;\n                3'b010 : alu_op = AluOp::Slt;\n                3'b011 : alu_op = AluOp::Sltu;\n                3'b100 : alu_op = AluOp::Xor;\n                3'b101 : alu_op = if alt ? AluOp::Sra : AluOp::Srl;\n                3'b110 : alu_op = AluOp::Or;\n                default: alu_op = AluOp::And;\n            }\n        } else {\n            alu_op = AluOp::Add; // 位址計算\n        }\n    }\n\n    let alu_b: logic<32> = if opcode == Opcode::RType || opcode == Opcode::Branch ? rs2_data : imm;\n    var alu_out: logic<32>;\n    inst u_alu: Alu (\n        i_op : alu_op  ,\n        i_a  : rs1_data,\n        i_b  : alu_b   ,\n        o_res: alu_out ,\n    );\n\n    // --- 分支條件 ---\n    var take: logic;\n    always_comb {\n        case funct3 {\n            3'b000 : take = rs1_data == rs2_data;\n            3'b001 : take = rs1_data != rs2_data;\n            3'b100 : take = $signed(rs1_data) <: $signed(rs2_data);\n            3'b101 : take = $signed(rs1_data) >= $signed(rs2_data);\n            3'b110 : take = rs1_data <: rs2_data;\n            3'b111 : take = rs1_data >= rs2_data;\n            default: take = 1'b0;\n        }\n    }\n\n    let pc_plus_4 : logic<32> = pc + 32'd4;\n    let branch_tgt: logic<32> = pc + imm;\n    var next_pc   : logic<32>;\n    always_comb {\n        case opcode {\n            Opcode::Jal   : next_pc = branch_tgt;\n            Opcode::Jalr  : next_pc = {alu_out[31:1], 1'b0};\n            Opcode::Branch: next_pc = if take ? branch_tgt : pc_plus_4;\n            default       : next_pc = pc_plus_4;\n        }\n    }\n    // 跳到不是 4 的倍數的位址（沒有 C 擴充）：例外。jal / jalr 不用等比較器；\n    // 分支的目標是 pc + imm，所以只看 imm[1]，再和 take 合起來（分支不寫暫存器和記憶體）\n    // 位址的低兩位元：rs1 + imm 的 2 位元加法（不用等 32 位元的 ALU）\n    let addr_lo   : logic<2> = rs1_data[1:0] + imm[1:0];\n    let bad_jal   : logic = (opcode == Opcode::Jal && imm[1]) || (opcode == Opcode::Jalr && addr_lo[1]);\n    let bad_branch: logic = opcode == Opcode::Branch && imm[1] && take;\n\n    // --- 控制與狀態暫存器（CSR，machine mode）---\n    var st_mie  : logic    ; // mstatus.MIE：全域中斷致能\n    var st_mpie : logic    ; // mstatus.MPIE：進入陷阱前的 MIE\n    var ie_msie : logic    ; // mie.MSIE / MTIE / MEIE\n    var ie_mtie : logic    ;\n    var ie_meie : logic    ;\n    var mtvec   : logic<32>;\n    var mscratch: logic<32>;\n    var mepc    : logic<32>;\n    var mcause  : logic<5> ; // {interrupt, code}：只有這些原因\n    var minstret: logic<32>;\n\n    let csr_addr: logic<12> = ir[31:20];\n    // 先把位址換成編號（小的比較器），再用編號選值（窄的多工器）\n    var csr_idx : logic<4> ;\n    var csr_ok  : logic    ;\n    always_comb {\n        csr_ok = 1'b1;\n        case csr_addr {\n            12'h300                  : csr_idx = 4'd0; // mstatus（MPP 永遠是 M）\n            12'h301                  : csr_idx = 4'd1; // misa\n            12'h304                  : csr_idx = 4'd2; // mie\n            12'h305                  : csr_idx = 4'd3; // mtvec\n            12'h340                  : csr_idx = 4'd4; // mscratch\n            12'h341                  : csr_idx = 4'd5; // mepc\n            12'h342                  : csr_idx = 4'd6; // mcause\n            12'h343                  : csr_idx = 4'd7; // mtval\n            12'h344                  : csr_idx = 4'd8; // mip\n            12'hB00, 12'hC00, 12'hC01: csr_idx = 4'd9; // mcycle / cycle / time：都是 SoC 的 mtime（寫入忽略）\n            12'hB80, 12'hC80, 12'hC81: csr_idx = 4'd10;\n            12'hB02, 12'hC02         : csr_idx = 4'd11; // minstret / instret（32 bit，寫入忽略）\n            12'hB82, 12'hC82, 12'hF11, 12'hF12, 12'hF13, 12'hF14: csr_idx = 4'd12; // 0\n            default: {\n                csr_idx = 4'd12;\n                csr_ok  = 1'b0;\n            }\n        }\n    }\n    var csr_old: logic<32>;\n    always_comb {\n        case csr_idx {\n            4'd0   : csr_old = {19'd0, 2'b11, 3'd0, st_mpie, 3'd0, st_mie, 3'd0};\n            4'd1   : csr_old = 32'h4000_1101; // RV32 I M A\n            4'd2   : csr_old = {20'd0, ie_meie, 3'd0, ie_mtie, 3'd0, ie_msie, 3'd0};\n            4'd3   : csr_old = mtvec;\n            4'd4   : csr_old = mscratch;\n            4'd5   : csr_old = mepc;\n            4'd6   : csr_old = {mcause[4], 27'd0, mcause[3:0]};\n            4'd7   : csr_old = 32'd0; // mtval：唯讀 0（規格允許）\n            4'd8   : csr_old = {20'd0, i_irq_ext, 3'd0, i_irq_timer, 3'd0, i_irq_soft, 3'd0};\n            4'd9   : csr_old = i_mtime[31:0];\n            4'd10  : csr_old = i_mtime[63:32];\n            4'd11  : csr_old = minstret;\n            default: csr_old = 32'd0;\n        }\n    }\n    // csrrw(i) 一定寫入；csrrs(i) / csrrc(i) 在 rs1 / zimm 不是 0 時才寫\n    let csr_writes: logic     = funct3[1:0] == 2'b01 || rs1_idx != 5'd0;\n    let csr_bad   : logic     = !csr_ok || (csr_addr[11:10] == 2'b11 && csr_writes);\n    let csr_src   : logic<32> = if funct3[2] ? {27'd0, rs1_idx} : rs1_data;\n    var csr_new   : logic<32>;\n    always_comb {\n        case funct3[1:0] {\n            2'b01  : csr_new = csr_src;\n            2'b10  : csr_new = csr_old | csr_src;\n            default: csr_new = csr_old & ~csr_src;\n        }\n    }\n\n    // --- 合法的指令（其他都是 illegal instruction 例外）：Decode 那一拍判斷，存進 legal_r；\n    //     CSR 位址合不合法在 Exec 看（csr_bad）---\n    let c_f3 : logic<3> = cur[14:12];\n    let c_f7 : logic<7> = cur[31:25];\n    let c_f5 : logic<5> = cur[31:27];\n    var legal_d: logic;\n    always_comb {\n        case c_op {\n            Opcode::Lui, Opcode::Auipc, Opcode::Jal: legal_d = 1'b1;\n            Opcode::Jalr                           : legal_d = c_f3 == 3'd0;\n            Opcode::Branch                         : legal_d = c_f3 != 3'd2 && c_f3 != 3'd3;\n            Opcode::Load                           : legal_d = c_f3 != 3'd3 && c_f3 != 3'd6 && c_f3 != 3'd7;\n            Opcode::Store                          : legal_d = c_f3 <: 3'd3;\n            Opcode::IType                          : legal_d = if c_f3 == 3'd1 ? c_f7 == 7'd0 : if c_f3 == 3'd5 ? (c_f7 == 7'd0 || c_f7 == 7'h20) : 1'b1;\n            Opcode::RType                          : legal_d = c_f7 == 7'd0 || c_f7 == 7'd1 || (c_f7 == 7'h20 && (c_f3 == 3'd0 || c_f3 == 3'd5));\n            default: {\n                if c_op == 7'b0001111 {\n                    legal_d = c_f3 <: 3'd2;\n                } else if c_op == 7'b1110011 {\n                    legal_d = if c_f3 == 3'd0 ? (cur == 32'h0000_0073 || cur == 32'h0010_0073 || cur == 32'h3020_0073 || cur == 32'h1050_0073) : c_f3 != 3'd4;\n                } else if c_op == 7'b0101111 {\n                    legal_d = c_f3 == 3'd2 && (c_f5 == 5'b00010 || c_f5 == 5'b00011 || c_f5 == 5'b00001 || c_f5 == 5'b00000 || c_f5 == 5'b00100 || c_f5 == 5'b01100 || c_f5 == 5'b01000 || c_f5 == 5'b10000 || c_f5 == 5'b10100 || c_f5 == 5'b11000 || c_f5 == 5'b11100);\n                } else {\n                    legal_d = 1'b0;\n                }\n            }\n        }\n    }\n    var legal_r: logic;\n    let legal  : logic = legal_r && !(is_csr && csr_bad);\n\n    // --- 中斷：外部 > 軟體 > 計時器 ---\n    let pend_ext  : logic = i_irq_ext && ie_meie;\n    let pend_soft : logic = i_irq_soft && ie_msie;\n    let pend_timer: logic = i_irq_timer && ie_mtie;\n    let pending   : logic = pend_ext || pend_soft || pend_timer;\n    let irq       : logic = st_mie && pending;\n\n    // --- 位址沒對齊 ---\n    let mis_load : logic = (op_load && ((funct3[1:0] == 2'b10 && addr_lo != 2'd0) || (funct3[1:0] == 2'b01 && addr_lo[0]))) || (is_lr && addr_lo != 2'd0);\n    let mis_store: logic = (op_store && ((funct3 == 3'd2 && addr_lo != 2'd0) || (funct3 == 3'd1 && addr_lo[0]))) || ((is_sc || is_amo) && addr_lo != 2'd0);\n\n    // --- 陷阱（在 Exec 決定；陷入的指令不產生任何效果）---\n    // trap_fast：不用等分支比較器的陷阱（決定暫存器、記憶體、CSR 寫不寫）；\n    // trap = 再加上分支目標沒對齊（只決定下一個 pc）\n    var trap_fast : logic   ;\n    var trap_cause: logic<5>; // {interrupt, code}\n    always_comb {\n        trap_fast  = 1'b1;\n        trap_cause = 5'd0;\n        if irq {\n            trap_cause = {1'b1, if pend_ext ? 4'd11 : if pend_soft ? 4'd3 : 4'd7};\n        } else if !legal {\n            trap_cause = 5'd2;\n        } else if is_ecall {\n            trap_cause = 5'd11;\n        } else if is_ebreak {\n            trap_cause = 5'd3;\n        } else if mis_load {\n            trap_cause = 5'd4;\n        } else if mis_store {\n            trap_cause = 5'd6;\n        } else if bad_jal {\n            trap_cause = 5'd0;\n        } else {\n            trap_fast = 1'b0;\n        }\n    }\n    let trap: logic = trap_fast || bad_branch;\n\n    // --- 乘除法（反覆式，33 拍：32 次移位加 / 移位減，最後一拍修正正負號）---\n    var md_p  : logic<64>; // 乘：{部分積, 乘數}；除：{餘數, 商}\n    var md_b  : logic<32>; // |被乘數| 或 |除數|\n    var md_cnt: logic<6> ;\n    var md_f3 : logic<3> ;\n    var md_neg: logic    ;\n    var md_bz : logic    ;\n\n    let md_sa  : logic     = (funct3 == 3'd1 || funct3 == 3'd2 || funct3 == 3'd4 || funct3 == 3'd6) && rs1_data[31];\n    let md_sb  : logic     = (funct3 == 3'd1 || funct3 == 3'd4 || funct3 == 3'd6) && rs2_data[31];\n    let md_absa: logic<32> = if md_sa ? 32'd0 - rs1_data : rs1_data;\n    let md_absb: logic<32> = if md_sb ? 32'd0 - rs2_data : rs2_data;\n\n    // 一個 33 位元加減法器：乘法加 md_b（乘數這位是 1 時），除法從左移後的餘數減 md_b\n    let md_sh  : logic<64> = {md_p[62:0], 1'b0};\n    let md_div : logic     = md_f3[2];\n    let md_x   : logic<33> = {1'b0, if md_div ? md_sh[63:32] : md_p[63:32]};\n    let md_y   : logic<33> = if md_div ? ~{1'b0, md_b} : if md_p[0] ? {1'b0, md_b} : 33'd0;\n    let md_sum : logic<33> = md_x + md_y + {32'd0, md_div}; // 減法 = 加上反相再加一\n    let md_diff: logic<33> = md_sum;\n    // 結果：先選低半或高半，再一起取負（乘積的高半取負 = ~高半 + (低半 == 0)）\n    let md_hi  : logic     = md_f3 == 3'd1 || md_f3 == 3'd2 || md_f3 == 3'd3 || md_f3 == 3'd6 || md_f3 == 3'd7;\n    let md_sel : logic<32> = if md_hi ? md_p[63:32] : md_p[31:0];\n    let md_cin : logic     = if md_f3[2] ? 1'b1 : md_f3 == 3'd0 || md_p[31:0] == 32'd0;\n    let md_sgn : logic<32> = if md_neg ? ~md_sel + {31'd0, md_cin} : md_sel;\n    var md_res : logic<32>;\n    always_comb {\n        if md_bz && md_f3[2:1] == 2'b10 {\n            md_res = 32'hffff_ffff; // 除以 0：商 = -1（餘數自然就是被除數）\n        } else {\n            md_res = md_sgn;\n        }\n    }\n\n    // --- 寫回 ---\n    var wb_data: logic<32>;\n    always_comb {\n        case opcode {\n            Opcode::Jal, Opcode::Jalr: wb_data = pc_plus_4;\n            Opcode::Lui              : wb_data = imm;\n            Opcode::Auipc            : wb_data = branch_tgt;\n            default                  : wb_data = if is_csr ? csr_old : alu_out;\n        }\n    }\n    let writes: logic = (opcode == Opcode::RType && !muldiv) || opcode == Opcode::IType || opcode == Opcode::Jal || opcode == Opcode::Jalr || opcode == Opcode::Lui || opcode == Opcode::Auipc || is_csr;\n\n    // --- load：從讀出的字取出 byte / halfword ---\n    let load_word: logic<32> = i_rdata >> {lsaddr[1:0], 3'b000};\n    var load_data: logic<32>;\n    always_comb {\n        case funct3 {\n            3'b000 : load_data = {load_word[7] repeat 24, load_word[7:0]};\n            3'b001 : load_data = {load_word[15] repeat 16, load_word[15:0]};\n            3'b100 : load_data = {24'd0, load_word[7:0]};\n            3'b101 : load_data = {16'd0, load_word[15:0]};\n            default: load_data = load_word;\n        }\n    }\n\n    // --- AMO：讀出的舊值和 rs2 算出新值（Mem 那一拍寫回）---\n    // min / max：一個比較器（有號時把最高位元反相），funct5[2] = max，funct5[3] = 無號\n    let amo_x  : logic<32> = {i_rdata[31] ^ !funct5[3], i_rdata[30:0]};\n    let amo_y  : logic<32> = {rs2_data[31] ^ !funct5[3], rs2_data[30:0]};\n    let amo_old: logic     = (amo_x <: amo_y) ^ funct5[2]; // 選舊值\n    var amo_new: logic<32>;\n    always_comb {\n        case funct5 {\n            5'b00001: amo_new = rs2_data; // swap\n            5'b00000: amo_new = i_rdata + rs2_data;\n            5'b00100: amo_new = i_rdata ^ rs2_data;\n            5'b01100: amo_new = i_rdata & rs2_data;\n            5'b01000: amo_new = i_rdata | rs2_data;\n            default : amo_new = if amo_old ? i_rdata : rs2_data; // min / max / minu / maxu\n        }\n    }\n\n    // --- store：資料複製到每個位元組位置，加上 byte strobe ---\n    var store_data: logic<32>;\n    var store_strb: logic<4> ;\n    always_comb {\n        case funct3 {\n            3'b000: {\n                store_data = {rs2_data[7:0] repeat 4};\n                store_strb = 4'b0001 << addr_lo;\n            }\n            3'b001: {\n                store_data = {rs2_data[15:0] repeat 2};\n                store_strb = 4'b0011 << addr_lo;\n            }\n            default: {\n                store_data = rs2_data;\n                store_strb = 4'b1111;\n            }\n        }\n    }\n\n    // --- LR / SC 的保留 ---\n    var resv_v : logic    ;\n    var resv_a : logic<32>;\n    let sc_ok  : logic     = resv_v && resv_a == rs1_data; // A 擴充的位址就是 rs1（不經過 ALU，路徑短）\n\n    // Exec 之後的 pc：陷阱 → mtvec，mret → mepc\n    let reads_mem: logic     = op_load || is_lr || is_amo;\n    // Exec 送出的下一個讀取位址：不等陷阱（陷入時改走 Fetch，從 mtvec 重新取指令）；\n    // 分支條件 take 只進最後一個多工器（其他的選擇先做好）\n    let taken    : logic     = opcode == Opcode::Branch && take;\n    var other_pc : logic<32>;\n    always_comb {\n        case opcode {\n            Opcode::Jal : other_pc = branch_tgt;\n            Opcode::Jalr: other_pc = {alu_out[31:1], 1'b0};\n            default     : other_pc = if is_mret ? mepc : pc_plus_4;\n        }\n    }\n    let exec_pc  : logic<32> = if taken ? branch_tgt : other_pc;\n    let exec_rd  : logic<32> = if reads_mem ? alu_out : other_pc; // 不是分支時的讀取位址\n\n    // --- 狀態機與記憶體埠 ---\n    always_comb {\n        o_re    = 1'b0;\n        o_raddr = pc;\n        o_waddr = alu_out;\n        o_wdata = store_data;\n        o_wstrb = 4'd0;\n        rf_we   = 1'b0;\n        rf_wd   = wb_data;\n        if i_run {\n            case state {\n                FETCH: o_re = 1'b1;\n                EXEC : {\n                    // 陷入的 load 不讀（周邊的讀取有副作用）\n                    o_raddr = if taken ? branch_tgt : exec_rd;\n                    if reads_mem {\n                        o_re = !trap_fast;\n                    } else if !muldiv && !(is_wfi && !pending) {\n                        o_re = 1'b1;\n                    }\n                    if !trap_fast {\n                        o_wstrb = if op_store || (is_sc && sc_ok) ? store_strb : 4'd0;\n                        rf_we   = (writes || is_sc) && rd_idx != 5'd0;\n                        rf_wd   = if is_sc ? {31'd0, !sc_ok} : wb_data;\n                    }\n                }\n                MEM: {\n                    o_re    = 1'b1;\n                    rf_we   = rd_idx != 5'd0;\n                    rf_wd   = load_data; // LR / AMO 的 funct3 是 2：整個字\n                    o_waddr = lsaddr;\n                    o_wdata = amo_new;\n                    o_wstrb = if is_amo ? 4'b1111 : 4'd0;\n                }\n                MULDIV: if md_cnt == 6'd32 {\n                    o_re  = 1'b1;\n                    rf_we = rd_idx != 5'd0;\n                    rf_wd = md_res;\n                }\n                WFI    : o_re = pending;\n                default: {}\n            }\n        }\n    }\n\n    let exec   : logic = i_run && state == EXEC;\n    let csr_we : logic = exec && !trap_fast && is_csr && csr_writes;\n    let retired: logic = exec && !trap;\n\n    always_ff {\n        if_reset {\n            state    = FETCH;\n            pc       = 32'd0;\n            ir       = 32'd0;\n            imm      = 32'd0;\n            legal_r  = 1'b0;\n            rs1_zero = 1'b1;\n            rs2_zero = 1'b1;\n            lsaddr   = 32'd0;\n            st_mie   = 1'b0;\n            st_mpie  = 1'b0;\n            ie_msie  = 1'b0;\n            ie_mtie  = 1'b0;\n            ie_meie  = 1'b0;\n            mtvec    = 32'd0;\n            mscratch = 32'd0;\n            mepc     = 32'd0;\n            mcause   = 5'd0;\n            md_p     = 64'd0;\n            md_b     = 32'd0;\n            md_cnt   = 6'd0;\n            md_f3    = 3'd0;\n            md_neg   = 1'b0;\n            md_bz    = 1'b0;\n            resv_v   = 1'b0;\n            resv_a   = 32'd0;\n        } else if !i_run {\n            state = FETCH;\n            pc    = 32'd0;\n        } else {\n            case state {\n                FETCH : state = DECODE;\n                DECODE: {\n                    ir      = i_rdata;\n                    imm      = imm_d;\n                    legal_r  = legal_d;\n                    rs1_zero = cur[19:15] == 5'd0;\n                    rs2_zero = cur[24:20] == 5'd0;\n                    state   = EXEC;\n                }\n                EXEC: {\n                    lsaddr = alu_out;\n                    pc     = exec_pc;\n                    if trap {\n                        mepc    = pc;\n                        mcause  = if trap_fast ? trap_cause : 5'd0;\n                        st_mpie = st_mie;\n                        st_mie  = 1'b0;\n                        resv_v  = 1'b0;\n                        pc      = {mtvec[31:2], 2'b00};\n                        state   = FETCH;\n                    } else {\n                        if is_mret {\n                            st_mie  = st_mpie;\n                            st_mpie = 1'b1;\n                        }\n                        if is_sc {\n                            resv_v = 1'b0;\n                        }\n                        if csr_we {\n                            case csr_idx {\n                                4'd0: {\n                                    st_mie  = csr_new[3];\n                                    st_mpie = csr_new[7];\n                                }\n                                4'd2: {\n                                    ie_msie = csr_new[3];\n                                    ie_mtie = csr_new[7];\n                                    ie_meie = csr_new[11];\n                                }\n                                4'd3   : mtvec    = {csr_new[31:2], 2'b00};\n                                4'd4   : mscratch = csr_new;\n                                4'd5   : mepc     = {csr_new[31:2], 2'b00};\n                                4'd6   : mcause   = {csr_new[31], csr_new[3:0]};\n                                default: {}\n                            }\n                        }\n                        if muldiv {\n                            md_p   = {32'd0, if funct3[2] ? md_absa : md_absb};\n                            md_b   = if funct3[2] ? md_absb : md_absa;\n                            md_cnt = 6'd0;\n                            md_f3  = funct3;\n                            md_neg = if funct3 == 3'd6 ? md_sa : md_sa ^ md_sb;\n                            md_bz  = rs2_data == 32'd0;\n                            state  = MULDIV;\n                        } else if reads_mem {\n                            state = MEM;\n                        } else if is_wfi && !pending {\n                            state = WFI;\n                        } else {\n                            state = DECODE;\n                        }\n                    }\n                }\n                MEM: {\n                    if is_lr {\n                        resv_v = 1'b1;\n                        resv_a = lsaddr;\n                    }\n                    state = DECODE; // 下一個指令的讀取已經送出\n                }\n                MULDIV: {\n                    if md_cnt == 6'd32 {\n                        state = DECODE;\n                    } else {\n                        md_cnt = md_cnt + 6'd1;\n                        if md_f3[2] {\n                            md_p = if md_diff[32] ? md_sh : {md_diff[31:0], md_sh[31:1], 1'b1};\n                        } else {\n                            md_p = {md_sum, md_p[31:1]};\n                        }\n                    }\n                }\n                WFI: if pending {\n                    state = DECODE;\n                }\n                default: state = FETCH;\n            }\n        }\n    }\n\n    // minstret：每個完成的指令加一（mcycle / time 讀的是 SoC 的 mtime）\n    always_ff {\n        if_reset {\n            minstret = 32'd0;\n        } else if retired {\n            minstret = minstret + 32'd1;\n        }\n    }\n}\n\n// 8 KB 記憶體：四個 8 bit 寬的位元組通道，store 依 byte strobe 只寫部分通道\nmodule RvMem #(\n    param AW: u32 = 11, // 字位址寬度（2^AW 個 32 bit 字）\n) (\n    i_clk  : input  clock    ,\n    i_re   : input  logic    ,\n    i_raddr: input  logic<AW>,\n    o_rdata: output logic<32>,\n    i_wstrb: input  logic<4> ,\n    i_waddr: input  logic<AW>,\n    i_wdata: input  logic<32>,\n) {\n    inst b0: SyncRam #(ADDR_W: AW, DATA_W: 8) (i_clk, i_we: i_wstrb[0], i_waddr, i_wdata: i_wdata[7:0], i_re, i_raddr, o_rdata: o_rdata[7:0]);\n    inst b1: SyncRam #(ADDR_W: AW, DATA_W: 8) (i_clk, i_we: i_wstrb[1], i_waddr, i_wdata: i_wdata[15:8], i_re, i_raddr, o_rdata: o_rdata[15:8]);\n    inst b2: SyncRam #(ADDR_W: AW, DATA_W: 8) (i_clk, i_we: i_wstrb[2], i_waddr, i_wdata: i_wdata[23:16], i_re, i_raddr, o_rdata: o_rdata[23:16]);\n    inst b3: SyncRam #(ADDR_W: AW, DATA_W: 8) (i_clk, i_we: i_wstrb[3], i_waddr, i_wdata: i_wdata[31:24], i_re, i_raddr, o_rdata: o_rdata[31:24]);\n}\n\n// CPU + 記憶體 + 周邊。i_ld = 1 時 CPU 停住，記憶體埠交給載入埠（testbench 用來放程式、讀結果）\nmodule RvSoc #(\n    param MEM_AW: u32 = 11 , // 2^MEM_AW 個字（11 = 8 KB）\n    param CPB   : u32 = 104, // UART 每位元時脈數（12 MHz / 115200）\n) (\n    i_clk     : input  clock        ,\n    i_rst     : input  reset        ,\n    i_ld      : input  logic        ,\n    i_ld_we   : input  logic        ,\n    i_ld_addr : input  logic<MEM_AW>,\n    i_ld_wdata: input  logic<32>    ,\n    o_ld_rdata: output logic<32>    ,\n    i_btn     : input  logic<3>     ,\n    i_sw      : input  logic<8>     ,\n    i_rx      : input  logic        ,\n    o_tx      : output logic        ,\n    o_led     : output logic<8>     ,\n    o_xwe     : output logic        , // 寫到 0x1000_2000 以上：給外加的周邊\n    o_xaddr   : output logic<14>    , // 位址的 bit 15..2\n    o_xdata   : output logic<32>    ,\n) {\n    var raddr: logic<32>;\n    var re   : logic    ;\n    var rdata: logic<32>;\n    var waddr: logic<32>;\n    var wstrb: logic<4> ;\n    var wdata: logic<32>;\n\n    var mtime   : logic<32>;\n    var mtimecmp: logic<32>;\n    var msip    : logic    ;\n    var rx_full : logic    ;\n\n    inst u_cpu: RvCore (\n        i_clk      : i_clk              ,\n        i_rst      : i_rst              ,\n        i_run      : !i_ld              ,\n        o_raddr    : raddr              ,\n        o_re       : re                 ,\n        i_rdata    : rdata              ,\n        o_waddr    : waddr              ,\n        o_wstrb    : wstrb              ,\n        o_wdata    : wdata              ,\n        i_irq_timer: mtime >= mtimecmp  ,\n        i_irq_soft : msip               ,\n        i_irq_ext  : rx_full            ,\n        i_mtime    : {32'd0, mtime}     ,\n    );\n\n    // --- 記憶體（載入埠優先）---\n    let io_r: logic = raddr[28];\n    let io_w: logic = waddr[28];\n    var mem_rdata: logic<32>;\n    inst u_mem: RvMem #(AW: MEM_AW) (\n        i_clk  : i_clk                                                 ,\n        i_re   : i_ld || (re && !io_r)                                 ,\n        i_raddr: if i_ld ? i_ld_addr : raddr[MEM_AW + 1:2]             ,\n        o_rdata: mem_rdata                                             ,\n        i_wstrb: if i_ld ? {i_ld_we repeat 4} : if io_w ? 4'd0 : wstrb,\n        i_waddr: if i_ld ? i_ld_addr : waddr[MEM_AW + 1:2]             ,\n        i_wdata: if i_ld ? i_ld_wdata : wdata                          ,\n    );\n    assign o_ld_rdata = mem_rdata;\n\n    // --- 周邊 ---\n    var led    : logic<8> ;\n    var btn_s  : logic<3> ;\n    var sw_s   : logic<8> ;\n    var rx_s   : logic<2> ;\n    var rx_byte: logic<8> ;\n    var tx_go  : logic    ;\n    var tx_byte: logic<8> ;\n    var tx_rdy : logic    ;\n    var rx_v   : logic    ;\n    var rx_d   : logic<8> ;\n    var io_sel : logic    ; // 上一拍讀的是周邊\n    var io_data: logic<32>;\n\n    inst u_tx: UartTx #(CLKS_PER_BIT: CPB) (\n        i_clk  : i_clk  ,\n        i_rst  : i_rst  ,\n        i_valid: tx_go  ,\n        i_data : tx_byte,\n        o_ready: tx_rdy ,\n        o_tx   : o_tx   ,\n    );\n    inst u_rx: UartRx #(CLKS_PER_BIT: CPB) (\n        i_clk  : i_clk  ,\n        i_rst  : i_rst  ,\n        i_rx   : rx_s[1],\n        o_valid: rx_v   ,\n        o_data : rx_d   ,\n    );\n\n    let wr_any: logic = !i_ld && io_w && wstrb != 4'd0;\n    let wr_io : logic = wr_any && waddr[15:13] == 3'd0;\n    assign o_xwe   = wr_any && waddr[15:13] != 3'd0;\n    assign o_xaddr = waddr[15:2];\n    assign o_xdata = wdata;\n    let rd_io: logic = !i_ld && re && io_r;\n\n    always_ff {\n        if_reset {\n            led      = 0;\n            mtime    = 0;\n            mtimecmp = 32'hffff_ffff;\n            msip     = 0;\n            btn_s   = 0;\n            sw_s    = 0;\n            rx_s    = 2'b11;\n            rx_byte = 0;\n            rx_full = 0;\n            tx_go   = 0;\n            tx_byte = 0;\n            io_sel  = 0;\n            io_data = 0;\n        } else {\n            mtime = mtime + 32'd1;\n            btn_s = i_btn;\n            sw_s  = i_sw;\n            rx_s  = {rx_s[0], i_rx};\n            tx_go = 0;\n            if wr_io {\n                case waddr[5:2] {\n                    4'd0: led = wdata[7:0];\n                    4'd2: {\n                        tx_go   = 1;\n                        tx_byte = wdata[7:0];\n                    }\n                    4'd4   : mtime    = wdata;\n                    4'd6   : mtimecmp = wdata;\n                    4'd8   : msip     = wdata[0];\n                    default: {}\n                }\n            }\n            if rx_v {\n                rx_byte = rx_d;\n                rx_full = 1;\n            } else if rd_io && raddr[5:2] == 4'd2 {\n                rx_full = 0;\n            }\n            io_sel = rd_io;\n            if rd_io {\n                case raddr[5:2] {\n                    4'd0   : io_data = {24'd0, led};\n                    4'd1   : io_data = {16'd0, sw_s, 5'd0, btn_s};\n                    4'd2   : io_data = {24'd0, rx_byte};\n                    4'd3   : io_data = {30'd0, rx_full, !tx_rdy || tx_go};\n                    4'd4   : io_data = mtime;\n                    4'd6   : io_data = mtimecmp;\n                    4'd8   : io_data = {31'd0, msip};\n                    default: io_data = 32'd0;\n                }\n            }\n        }\n    }\n\n    assign rdata = if io_sel ? io_data : mem_rdata;\n    assign o_led = led;\n}\n\n// FPGA 頂層：iCEBreaker（BTN_N 重設，BTN1-3，USB 序列埠，PMOD1A 的 8 個輸出（LED 模組、七段顯示器…），\n// PMOD1B 的 8 個輸入（開關模組））。\n// 程式放在 block RAM 的初值裡（veryl-eda 把程式寫進位元流）\nmodule RvBoard (\n    i_clk: input  clock   ,\n    i_rst: input  reset   ,\n    i_btn: input  logic<3>,\n    i_sw : input  logic<8>,\n    i_rx : input  logic   ,\n    o_tx : output logic   ,\n    o_led: output logic<8>,\n) {\n    inst u_soc: RvSoc (\n        i_clk     : i_clk,\n        i_rst     : i_rst,\n        i_ld      : 1'b0 ,\n        i_ld_we   : 1'b0 ,\n        i_ld_addr : 11'd0,\n        i_ld_wdata: 32'd0,\n        o_ld_rdata: _    ,\n        i_btn     : i_btn,\n        i_sw      : i_sw ,\n        i_rx      : i_rx ,\n        o_tx      : o_tx ,\n        o_led     : o_led,\n        o_xwe     : _    ,\n        o_xaddr   : _    ,\n        o_xdata   : _    ,\n    );\n}\n\n// 測試：把 rv32i_test.S（資料在 0x300，rvsoc_rom.veryl）載入 1 KB 的記憶體、執行，再讀回簽章\n// （閘級模擬時記憶體是一個個正反器，所以測試用小的記憶體）\n#[test(test_rvsoc)]\nmodule TestRvSoc {\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen(clk);\n\n    var ld      : logic    ;\n    var ld_we   : logic    ;\n    var ld_addr : logic<8> ;\n    var ld_rdata: logic<32>;\n    var prog    : logic<32>;\n    var tx      : logic    ;\n    var led     : logic<8> ;\n\n    inst u_prog: RvTestProg (\n        i_addr: {22'd0, ld_addr, 2'b00},\n        o_inst: prog                    ,\n    );\n\n    inst dut: RvSoc #(MEM_AW: 8, CPB: 4) (\n        i_clk     : clk     ,\n        i_rst     : rst     ,\n        i_ld      : ld      ,\n        i_ld_we   : ld_we   ,\n        i_ld_addr : ld_addr ,\n        i_ld_wdata: prog    ,\n        o_ld_rdata: ld_rdata,\n        i_btn     : 3'd0    ,\n        i_sw      : 8'd0    ,\n        i_rx      : 1'b1    ,\n        o_tx      : tx      ,\n        o_led     : led     ,\n        o_xwe     : _       ,\n        o_xaddr   : _       ,\n        o_xdata   : _       ,\n    );\n\n    initial {\n        // 1. 載入程式（256 個字）\n        ld      = 1;\n        ld_we   = 1;\n        ld_addr = 0;\n        rst.assert();\n        for _i in 0..256 {\n            clk.next();\n            ld_addr = ld_addr + 8'd1;\n        }\n        // 2. 執行\n        ld_we = 0;\n        ld    = 0;\n        clk.next(1000);\n        // 3. 讀回 0x1000 起的簽章（同步讀取：下一拍才有資料）\n        ld = 1;\n        ld_addr = 8'd239; clk.next(); $assert(ld_rdata == 32'h00000001, \"program finished\");\n        ld_addr = 8'd192; clk.next(); $assert(ld_rdata == 32'h12345678, \"lui + addi\");\n        ld_addr = 8'd193; clk.next(); $assert(ld_rdata == 32'h00000010, \"auipc\");\n        ld_addr = 8'd194; clk.next(); $assert(ld_rdata == 32'hffffffff, \"lui + srai\");\n        ld_addr = 8'd195; clk.next(); $assert(ld_rdata == 32'hfffffffb, \"add\");\n        ld_addr = 8'd196; clk.next(); $assert(ld_rdata == 32'h0000000b, \"sub\");\n        ld_addr = 8'd197; clk.next(); $assert(ld_rdata == 32'hffffffc0, \"sll\");\n        ld_addr = 8'd198; clk.next(); $assert(ld_rdata == 32'h1fffffff, \"srl\");\n        ld_addr = 8'd199; clk.next(); $assert(ld_rdata == 32'hffffffff, \"sra\");\n        ld_addr = 8'd200; clk.next(); $assert(ld_rdata == 32'hc0000000, \"slli\");\n        ld_addr = 8'd201; clk.next(); $assert(ld_rdata == 32'h0000000f, \"srli\");\n        ld_addr = 8'd202; clk.next(); $assert(ld_rdata == 32'hfffffffc, \"srai\");\n        ld_addr = 8'd203; clk.next(); $assert(ld_rdata == 32'hedcba980, \"xor\");\n        ld_addr = 8'd204; clk.next(); $assert(ld_rdata == 32'hfffffffc, \"xori\");\n        ld_addr = 8'd205; clk.next(); $assert(ld_rdata == 32'h1234567b, \"or\");\n        ld_addr = 8'd206; clk.next(); $assert(ld_rdata == 32'h000007f3, \"ori\");\n        ld_addr = 8'd207; clk.next(); $assert(ld_rdata == 32'h12345678, \"and\");\n        ld_addr = 8'd208; clk.next(); $assert(ld_rdata == 32'h00000078, \"andi\");\n        ld_addr = 8'd209; clk.next(); $assert(ld_rdata == 32'h00000001, \"slt\");\n        ld_addr = 8'd210; clk.next(); $assert(ld_rdata == 32'h00000000, \"sltu\");\n        ld_addr = 8'd211; clk.next(); $assert(ld_rdata == 32'h00000000, \"slti\");\n        ld_addr = 8'd212; clk.next(); $assert(ld_rdata == 32'h00000001, \"sltiu\");\n        ld_addr = 8'd213; clk.next(); $assert(ld_rdata == 32'h00000006, \"sll uses rs2[4:0]\");\n        ld_addr = 8'd214; clk.next(); $assert(ld_rdata == 32'h000000aa, \"beq/bne/blt/bge\");\n        ld_addr = 8'd215; clk.next(); $assert(ld_rdata == 32'h0000000a, \"bltu/bgeu\");\n        ld_addr = 8'd216; clk.next(); $assert(ld_rdata == 32'h0000000f, \"backward branch loop\");\n        ld_addr = 8'd217; clk.next(); $assert(ld_rdata == 32'h00000000, \"jal/jalr skip\");\n        ld_addr = 8'd218; clk.next(); $assert(ld_rdata == 32'h00000008, \"jalr link\");\n        ld_addr = 8'd219; clk.next(); $assert(ld_rdata == 32'hfffffffc, \"jal link\");\n        ld_addr = 8'd220; clk.next(); $assert(ld_rdata == 32'h00000078, \"lb\");\n        ld_addr = 8'd221; clk.next(); $assert(ld_rdata == 32'h00000012, \"lb offset 3\");\n        ld_addr = 8'd222; clk.next(); $assert(ld_rdata == 32'hfffffff8, \"lb sign\");\n        ld_addr = 8'd223; clk.next(); $assert(ld_rdata == 32'h000000f8, \"lbu\");\n        ld_addr = 8'd224; clk.next(); $assert(ld_rdata == 32'h00001234, \"lh\");\n        ld_addr = 8'd225; clk.next(); $assert(ld_rdata == 32'hfffffff8, \"lh sign\");\n        ld_addr = 8'd226; clk.next(); $assert(ld_rdata == 32'h0000ffff, \"lhu\");\n        ld_addr = 8'd227; clk.next(); $assert(ld_rdata == 32'h00005678, \"lhu offset 0\");\n        ld_addr = 8'd228; clk.next(); $assert(ld_rdata == 32'h12f80378, \"sb\");\n        ld_addr = 8'd229; clk.next(); $assert(ld_rdata == 32'h0003fff8, \"sh\");\n        ld_addr = 8'd230; clk.next(); $assert(ld_rdata == 32'h56785678, \"sh both halves\");\n        ld_addr = 8'd231; clk.next(); $assert(ld_rdata == 32'h00000000, \"x0 is zero\");\n        $finish();\n    }\n}\n"},{"name":"rv32i.veryl","src":"// ==========================================\n// 1. 定義常數與列舉\n// ==========================================\npackage RiscvTypes {\n    enum AluOp: logic<4> {\n        Add,\n        Sub,\n        And,\n        Or,\n        Slt,\n        Sltu,\n        Xor,\n        Sll,\n        Srl,\n        Sra,\n    }\n\n    enum Opcode: logic<7> {\n        RType  = 7'b0110011,\n        IType  = 7'b0010011,\n        Load   = 7'b0000011,\n        Store  = 7'b0100011,\n        Branch = 7'b1100011,\n        Jal    = 7'b1101111,\n        Jalr   = 7'b1100111,\n        Lui    = 7'b0110111,\n        Auipc  = 7'b0010111,\n    }\n}\n\n// ==========================================\n// 2. 算術邏輯單元（ALU）\n// ==========================================\nmodule Alu (\n    i_op : input  RiscvTypes::AluOp,\n    i_a  : input  logic<32>,\n    i_b  : input  logic<32>,\n    o_res: output logic<32>,\n) {\n    import RiscvTypes::*;\n\n    always_comb {\n        case i_op {\n            AluOp::Add : o_res = i_a + i_b;\n            AluOp::Sub : o_res = i_a - i_b;\n            AluOp::And : o_res = i_a & i_b;\n            AluOp::Or  : o_res = i_a | i_b;\n            AluOp::Xor : o_res = i_a ^ i_b;\n            AluOp::Slt : o_res = {31'd0, $signed(i_a) <: $signed(i_b)};\n            AluOp::Sltu: o_res = {31'd0, i_a <: i_b};\n            // 移位量只取 i_b 的低 5 bit\n            AluOp::Sll: o_res = i_a << i_b[4:0];\n            AluOp::Srl: o_res = i_a >> i_b[4:0];\n            AluOp::Sra: o_res = $signed(i_a) >>> i_b[4:0];\n            default   : o_res = 32'd0;\n        }\n    }\n}\n\n// ==========================================\n// 3. 通用暫存器堆（Register File）\n// ==========================================\nmodule RegFile (\n    i_clk    : input  clock,\n    i_rst    : input  reset,\n    i_rs1_idx: input  logic<5>,\n    i_rs2_idx: input  logic<5>,\n    i_rd_idx : input  logic<5>,\n    i_rd_data: input  logic<32>,\n    i_rd_we  : input  logic,\n    o_rs1_val: output logic<32>,\n    o_rs2_val: output logic<32>,\n) {\n    var rf: logic<32> [32];\n\n    #[allow(missing_reset_statement)]\n    always_ff (i_clk, i_rst) {\n        if_reset {\n        } else if (i_rd_we && (i_rd_idx != 5'd0)) {\n            rf[i_rd_idx] = i_rd_data;\n        }\n    }\n\n    always_comb {\n        if i_rs1_idx == 5'd0 {\n            o_rs1_val = 32'd0;\n        } else {\n            o_rs1_val = rf[i_rs1_idx];\n        }\n\n        if i_rs2_idx == 5'd0 {\n            o_rs2_val = 32'd0;\n        } else {\n            o_rs2_val = rf[i_rs2_idx];\n        }\n    }\n}\n\n// ==========================================\n// 4. CPU 頂層模組（單週期 RV32I，不含 fence/ecall/ebreak/CSR）\n// ==========================================\n// 資料記憶體介面：o_dmem_addr 為位元組位址；寫入時 o_dmem_wdata 已對齊到\n// 32 bit 字中的位置，o_dmem_wstrb 指出要寫的位元組；讀取時 i_dmem_rdata\n// 是 o_dmem_addr 所在的整個字（由 CPU 取出 byte/halfword 並做符號擴展）。\nmodule RiscvCore (\n    i_clk       : input  clock,\n    i_rst       : input  reset,\n    o_imem_addr : output logic<32>,\n    i_imem_inst : input  logic<32>,\n    o_dmem_addr : output logic<32>,\n    o_dmem_wdata: output logic<32>,\n    o_dmem_wstrb: output logic<4>,\n    i_dmem_rdata: input  logic<32>,\n    o_dmem_we   : output logic,\n) {\n    import RiscvTypes::*;\n\n    var pc        : logic<32>;\n    var next_pc   : logic<32>;\n    var pc_plus_4 : logic<32>;\n    var branch_tgt: logic<32>;\n\n    var rs1_data  : logic<32>;\n    var rs2_data  : logic<32>;\n    var alu_src_b : logic<32>;\n    var alu_out   : logic<32>;\n    var imm       : logic<32>;\n    var wb_data   : logic<32>;\n    var load_data : logic<32>;\n    var store_data: logic<32>;\n    var store_strb: logic<4>;\n    var take      : logic;\n\n    var alu_op    : AluOp;\n    var arith_op  : AluOp;\n    var reg_write : logic;\n    var dmem_write: logic;\n\n    let opcode : logic<7> = i_imem_inst[6:0];\n    let rd_idx : logic<5> = i_imem_inst[11:7];\n    let funct3 : logic<3> = i_imem_inst[14:12];\n    let rs1_idx: logic<5> = i_imem_inst[19:15];\n    let rs2_idx: logic<5> = i_imem_inst[24:20];\n    let funct7 : logic<7> = i_imem_inst[31:25];\n\n    // --- 立即數解碼 ---\n    always_comb {\n        case opcode {\n            Opcode::IType, Opcode::Load, Opcode::Jalr:\n                imm = {i_imem_inst[31] repeat 20, i_imem_inst[31:20]};\n            Opcode::Store:\n                imm = {i_imem_inst[31] repeat 20, i_imem_inst[31:25], i_imem_inst[11:7]};\n            Opcode::Branch:\n                imm = {i_imem_inst[31] repeat 20, i_imem_inst[7], i_imem_inst[30:25], i_imem_inst[11:8], 1'b0};\n            Opcode::Jal:\n                imm = {i_imem_inst[31] repeat 12, i_imem_inst[19:12], i_imem_inst[20], i_imem_inst[30:21], 1'b0};\n            Opcode::Lui, Opcode::Auipc:\n                imm = {i_imem_inst[31:12], 12'd0};\n            default:\n                imm = 32'd0;\n        }\n    }\n\n    // --- 控制邏輯 ---\n    // funct7[5] 選 sub / sra；I-type 只有 srai 使用（addi 沒有減法版本）\n    let alt: logic = funct7[5] && (opcode == Opcode::RType || funct3 == 3'b101);\n\n    always_comb {\n        case funct3 {\n            3'b000 : arith_op = if alt ? AluOp::Sub : AluOp::Add;\n            3'b001 : arith_op = AluOp::Sll;\n            3'b010 : arith_op = AluOp::Slt;\n            3'b011 : arith_op = AluOp::Sltu;\n            3'b100 : arith_op = AluOp::Xor;\n            3'b101 : arith_op = if alt ? AluOp::Sra : AluOp::Srl;\n            3'b110 : arith_op = AluOp::Or;\n            default: arith_op = AluOp::And;\n        }\n    }\n\n    always_comb {\n        reg_write  = 1'b0;\n        dmem_write = 1'b0;\n        alu_op     = AluOp::Add;\n\n        case opcode {\n            Opcode::RType, Opcode::IType: {\n                reg_write = 1'b1;\n                alu_op    = arith_op;\n            }\n            Opcode::Load, Opcode::Jal, Opcode::Jalr, Opcode::Lui, Opcode::Auipc: {\n                reg_write = 1'b1;\n            }\n            Opcode::Store: {\n                dmem_write = 1'b1;\n            }\n            default: {}\n        }\n    }\n\n    // --- 分支條件（獨立的比較器，不經過 ALU）---\n    always_comb {\n        case funct3 {\n            3'b000 : take = rs1_data == rs2_data;                     // beq\n            3'b001 : take = rs1_data != rs2_data;                     // bne\n            3'b100 : take = $signed(rs1_data) <: $signed(rs2_data);   // blt\n            3'b101 : take = $signed(rs1_data) >= $signed(rs2_data);   // bge\n            3'b110 : take = rs1_data <: rs2_data;                     // bltu\n            3'b111 : take = rs1_data >= rs2_data;                     // bgeu\n            default: take = 1'b0;\n        }\n    }\n\n    // --- 載入：從整個字取出 byte / halfword ---\n    let byte_off : logic<2>  = alu_out[1:0];\n    let load_word: logic<32> = i_dmem_rdata >> {byte_off, 3'b000};\n\n    always_comb {\n        case funct3 {\n            3'b000 : load_data = {load_word[7] repeat 24, load_word[7:0]};   // lb\n            3'b001 : load_data = {load_word[15] repeat 16, load_word[15:0]}; // lh\n            3'b100 : load_data = {24'd0, load_word[7:0]};                    // lbu\n            3'b101 : load_data = {16'd0, load_word[15:0]};                   // lhu\n            default: load_data = load_word;                                  // lw\n        }\n    }\n\n    // --- 儲存：把資料複製到每個位元組位置，並產生 byte strobe ---\n    always_comb {\n        case funct3 {\n            3'b000: {\n                store_data = {rs2_data[7:0] repeat 4};\n                store_strb = 4'b0001 << byte_off;\n            }\n            3'b001: {\n                store_data = {rs2_data[15:0] repeat 2};\n                store_strb = 4'b0011 << byte_off;\n            }\n            default: {\n                store_data = rs2_data;\n                store_strb = 4'b1111;\n            }\n        }\n    }\n\n    // --- 多工器選擇 ---\n    always_comb {\n        if (opcode == Opcode::RType || opcode == Opcode::Branch) {\n            alu_src_b = rs2_data;\n        } else {\n            alu_src_b = imm;\n        }\n\n        case opcode {\n            Opcode::Load            : wb_data = load_data;\n            Opcode::Jal, Opcode::Jalr: wb_data = pc_plus_4;\n            Opcode::Lui             : wb_data = imm;\n            Opcode::Auipc           : wb_data = branch_tgt;\n            default                 : wb_data = alu_out;\n        }\n    }\n\n    // --- 模組例化 ---\n    inst u_rf: RegFile (\n        i_clk    : i_clk,\n        i_rst    : i_rst,\n        i_rs1_idx: rs1_idx,\n        i_rs2_idx: rs2_idx,\n        i_rd_idx : rd_idx,\n        i_rd_data: wb_data,\n        i_rd_we  : reg_write,\n        o_rs1_val: rs1_data,\n        o_rs2_val: rs2_data,\n    );\n\n    inst u_alu: Alu (\n        i_op : alu_op,\n        i_a  : rs1_data,\n        i_b  : alu_src_b,\n        o_res: alu_out,\n    );\n\n    // --- PC 計算 ---\n    assign pc_plus_4  = pc + 32'd4;\n    assign branch_tgt = pc + imm;\n\n    always_comb {\n        case opcode {\n            Opcode::Jal   : next_pc = branch_tgt;\n            Opcode::Jalr  : next_pc = {alu_out[31:1], 1'b0}; // (rs1 + imm) & ~1\n            Opcode::Branch: next_pc = if take ? branch_tgt : pc_plus_4;\n            default       : next_pc = pc_plus_4;\n        }\n    }\n\n    always_ff (i_clk, i_rst) {\n        if_reset {\n            pc = 32'd0;\n        } else {\n            pc = next_pc;\n        }\n    }\n\n    // --- 輸出埠綁定 ---\n    assign o_imem_addr  = pc;\n    assign o_dmem_addr  = alu_out;\n    assign o_dmem_wdata = store_data;\n    assign o_dmem_wstrb = store_strb;\n    assign o_dmem_we    = dmem_write;\n}\n\n// ==========================================\n// 5. RISC-V 核心整合測試（Testbench）\n// ==========================================\n// 程式在 examples/sw/rv32i_test.S（ROM 由 examples/sw/build.sh 產生成\n// rv32i_rom.veryl），涵蓋全部 RV32I 運算指令；結果寫入 dmem[0..47]。\n#[test(test_riscv_cpu)]\nmodule TestRiscvCore {\n    // 官方 testbench 元件：clk 本身即 clock 訊號，rst 綁定 clk\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen(clk);\n\n    var imem_addr : logic<32>;\n    var imem_inst : logic<32>;\n    var dmem_addr : logic<32>;\n    var dmem_wdata: logic<32>;\n    var dmem_wstrb: logic<4>;\n    var dmem_rdata: logic<32>;\n    var dmem_we   : logic;\n\n    // 模擬 Data RAM：64 字（256 bytes），依 byte strobe 寫入\n    var dmem: logic<32> [64];\n\n    let wmask: logic<32> = {dmem_wstrb[3] repeat 8, dmem_wstrb[2] repeat 8, dmem_wstrb[1] repeat 8, dmem_wstrb[0] repeat 8};\n\n    #[allow(missing_reset_statement)]\n    always_ff (clk, rst) {\n        if_reset {\n        } else if dmem_we {\n            dmem[dmem_addr[7:2]] = (dmem[dmem_addr[7:2]] & ~wmask) | (dmem_wdata & wmask);\n        }\n    }\n    assign dmem_rdata = dmem[dmem_addr[7:2]];\n\n    // 程式 ROM\n    inst u_rom: RiscvTestRom (\n        i_addr: imem_addr,\n        o_inst: imem_inst,\n    );\n\n    // 例化 CPU\n    inst dut: RiscvCore (\n        i_clk       : clk,\n        i_rst       : rst,\n        o_imem_addr : imem_addr,\n        i_imem_inst : imem_inst,\n        o_dmem_addr : dmem_addr,\n        o_dmem_wdata: dmem_wdata,\n        o_dmem_wstrb: dmem_wstrb,\n        i_dmem_rdata: dmem_rdata,\n        o_dmem_we   : dmem_we,\n    );\n\n    initial {\n        // 1. 重設後釋放，開始執行\n        rst.assert();\n\n        // 2. 執行到程式結束（停在 halt 迴圈）\n        clk.next(200);\n\n        // 3. 斷言驗證（期望值與 rv32i_test.S 的註解相同）\n        $assert(dmem[47] == 32'h00000001, \"program finished\");\n        $assert(dmem[0] == 32'h12345678, \"lui + addi\");\n        $assert(dmem[1] == 32'h00000010, \"auipc\");\n        $assert(dmem[2] == 32'hffffffff, \"lui + srai\");\n        $assert(dmem[3] == 32'hfffffffb, \"add\");\n        $assert(dmem[4] == 32'h0000000b, \"sub\");\n        $assert(dmem[5] == 32'hffffffc0, \"sll\");\n        $assert(dmem[6] == 32'h1fffffff, \"srl\");\n        $assert(dmem[7] == 32'hffffffff, \"sra\");\n        $assert(dmem[8] == 32'hc0000000, \"slli\");\n        $assert(dmem[9] == 32'h0000000f, \"srli\");\n        $assert(dmem[10] == 32'hfffffffc, \"srai\");\n        $assert(dmem[11] == 32'hedcba980, \"xor\");\n        $assert(dmem[12] == 32'hfffffffc, \"xori\");\n        $assert(dmem[13] == 32'h1234567b, \"or\");\n        $assert(dmem[14] == 32'h000007f3, \"ori\");\n        $assert(dmem[15] == 32'h12345678, \"and\");\n        $assert(dmem[16] == 32'h00000078, \"andi\");\n        $assert(dmem[17] == 32'h00000001, \"slt\");\n        $assert(dmem[18] == 32'h00000000, \"sltu\");\n        $assert(dmem[19] == 32'h00000000, \"slti\");\n        $assert(dmem[20] == 32'h00000001, \"sltiu\");\n        $assert(dmem[21] == 32'h00000006, \"sll uses rs2[4:0]\");\n        $assert(dmem[22] == 32'h000000aa, \"beq/bne/blt/bge\");\n        $assert(dmem[23] == 32'h0000000a, \"bltu/bgeu\");\n        $assert(dmem[24] == 32'h0000000f, \"backward branch loop\");\n        $assert(dmem[25] == 32'h00000000, \"jal/jalr skip\");\n        $assert(dmem[26] == 32'h00000008, \"jalr link\");\n        $assert(dmem[27] == 32'hfffffffc, \"jal link\");\n        $assert(dmem[28] == 32'h00000078, \"lb\");\n        $assert(dmem[29] == 32'h00000012, \"lb offset 3\");\n        $assert(dmem[30] == 32'hfffffff8, \"lb sign\");\n        $assert(dmem[31] == 32'h000000f8, \"lbu\");\n        $assert(dmem[32] == 32'h00001234, \"lh\");\n        $assert(dmem[33] == 32'hfffffff8, \"lh sign\");\n        $assert(dmem[34] == 32'h0000ffff, \"lhu\");\n        $assert(dmem[35] == 32'h00005678, \"lhu offset 0\");\n        $assert(dmem[36] == 32'h12f80378, \"sb\");\n        $assert(dmem[37] == 32'h0003fff8, \"sh\");\n        $assert(dmem[38] == 32'h56785678, \"sh both halves\");\n        $assert(dmem[39] == 32'h00000000, \"x0 is zero\");\n\n        $finish();\n    }\n}\n"},{"name":"sync_ram.veryl","src":"// ==========================================\n// 同步讀取 RAM：讀取位址在時脈正緣取樣，下一拍才有資料\n// （iCE40 block RAM 的行為：合成到 FPGA 時會變成 SB_RAM40_4K）\n// ==========================================\nmodule SyncRam #(\n    param ADDR_W: u32 = 9,\n    param DATA_W: u32 = 8,\n) (\n    i_clk  : input  clock,\n    i_we   : input  logic,\n    i_waddr: input  logic<ADDR_W>,\n    i_wdata: input  logic<DATA_W>,\n    i_re   : input  logic,\n    i_raddr: input  logic<ADDR_W>,\n    o_rdata: output logic<DATA_W>,\n) {\n    var mem: logic<DATA_W> [1 << ADDR_W];\n\n    always_ff (i_clk) {\n        if i_we {\n            mem[i_waddr] = i_wdata;\n        }\n        if i_re {\n            o_rdata = mem[i_raddr];\n        }\n    }\n}\n\n#[test(sync_ram_test)]\nmodule TestSyncRam {\n    inst clk: $tb::clock_gen;\n\n    var we   : logic;\n    var waddr: logic<9>;\n    var wdata: logic<8>;\n    var re   : logic;\n    var raddr: logic<9>;\n    var rdata: logic<8>;\n\n    inst u: SyncRam (\n        i_clk  : clk,\n        i_we   : we,\n        i_waddr: waddr,\n        i_wdata: wdata,\n        i_re   : re,\n        i_raddr: raddr,\n        o_rdata: rdata,\n    );\n\n    initial {\n        re = 1;\n        we = 1;\n        waddr = 9'd5;   wdata = 8'h5A; clk.next();\n        waddr = 9'd300; wdata = 8'hC3; clk.next();\n        waddr = 9'd511; wdata = 8'h7E; clk.next();\n        we = 0;\n\n        // 讀取：下一拍才出現\n        raddr = 9'd300; clk.next();\n        $assert(rdata == 8'hC3, \"read 300\");\n        raddr = 9'd5;   clk.next();\n        $assert(rdata == 8'h5A, \"read 5\");\n        raddr = 9'd511; clk.next();\n        $assert(rdata == 8'h7E, \"read 511\");\n\n        // 讀取致能關閉時輸出保持\n        re = 0;\n        raddr = 9'd5; clk.next();\n        $assert(rdata == 8'h7E, \"hold when re = 0\");\n\n        // 同一拍讀寫同一位址：讀到舊值\n        re = 1;\n        we = 1;\n        waddr = 9'd5; wdata = 8'h11; raddr = 9'd5; clk.next();\n        $assert(rdata == 8'h5A, \"read-during-write returns the old value\");\n        we = 0;\n        clk.next();\n        $assert(rdata == 8'h11, \"new value next cycle\");\n        $finish();\n    }\n}\n"},{"name":"uart.veryl","src":"// ==========================================\n// UART：8N1 傳送器與接收器（每個位元 CLKS_PER_BIT 個時脈）\n// ==========================================\nmodule UartTx #(\n    param CLKS_PER_BIT: u32 = 16,\n) (\n    i_clk  : input  clock    ,\n    i_rst  : input  reset    ,\n    i_valid: input  logic    ,\n    i_data : input  logic<8> ,\n    o_ready: output logic    ,\n    o_tx   : output logic    ,\n) {\n    var busy : logic    ;\n    var shift: logic<10>; // stop, data[7:0], start (LSB first)\n    var nbits: logic<4> ;\n    var cnt  : logic<16>;\n\n    always_ff {\n        if_reset {\n            busy  = 0;\n            shift = 10'h3ff;\n            nbits = 0;\n            cnt   = 0;\n        } else if !busy {\n            if i_valid {\n                busy  = 1;\n                shift = {1'b1, i_data, 1'b0};\n                nbits = 4'd10;\n                cnt   = 0;\n            }\n        } else if cnt == CLKS_PER_BIT - 1 {\n            cnt   = 0;\n            shift = {1'b1, shift[9:1]};\n            nbits = nbits - 4'd1;\n            if nbits == 4'd1 {\n                busy = 0;\n            }\n        } else {\n            cnt = cnt + 16'd1;\n        }\n    }\n\n    assign o_ready = !busy;\n    assign o_tx    = shift[0];\n}\n\nmodule UartRx #(\n    param CLKS_PER_BIT: u32 = 16,\n) (\n    i_clk  : input  clock   ,\n    i_rst  : input  reset   ,\n    i_rx   : input  logic   ,\n    o_valid: output logic   ,\n    o_data : output logic<8>,\n) {\n    var busy : logic    ;\n    var cnt  : logic<16>;\n    var nbits: logic<4> ;\n    var data : logic<8> ;\n    var valid: logic    ;\n\n    always_ff {\n        if_reset {\n            busy  = 0;\n            cnt   = 0;\n            nbits = 0;\n            data  = 0;\n            valid = 0;\n        } else {\n            valid = 0;\n            if !busy {\n                // start bit: wait half a bit, then sample in the middle\n                if !i_rx {\n                    busy  = 1;\n                    cnt   = CLKS_PER_BIT / 2;\n                    nbits = 0;\n                }\n            } else if cnt == CLKS_PER_BIT - 1 {\n                cnt = 0;\n                if nbits == 4'd9 {\n                    busy  = 0;\n                    valid = i_rx; // stop bit must be 1\n                } else {\n                    if nbits != 4'd0 {\n                        data = {i_rx, data[7:1]};\n                    }\n                    nbits = nbits + 4'd1;\n                }\n            } else {\n                cnt = cnt + 16'd1;\n            }\n        }\n    }\n\n    assign o_valid = valid;\n    assign o_data  = data;\n}\n\n// loopback: what the transmitter sends, the receiver gets back\nmodule UartLoop (\n    i_clk  : input  clock   ,\n    i_rst  : input  reset   ,\n    i_valid: input  logic   ,\n    i_data : input  logic<8>,\n    o_ready: output logic   ,\n    o_tx   : output logic   ,\n    o_valid: output logic   ,\n    o_data : output logic<8>,\n) {\n    var line: logic;\n\n    inst tx: UartTx #(CLKS_PER_BIT: 8) (\n        i_clk           ,\n        i_rst           ,\n        i_valid         ,\n        i_data          ,\n        o_ready         ,\n        o_tx   : line   ,\n    );\n    inst rx: UartRx #(CLKS_PER_BIT: 8) (\n        i_clk           ,\n        i_rst           ,\n        i_rx   : line   ,\n        o_valid         ,\n        o_data          ,\n    );\n    assign o_tx = line;\n}\n\n#[test(uart_test)]\nmodule TestUart {\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen(clk);\n\n    var valid : logic   ;\n    var data  : logic<8>;\n    var ready : logic   ;\n    var tx    : logic   ;\n    var rvalid: logic   ;\n    var rdata : logic<8>;\n\n    inst u: UartLoop (\n        i_clk  : clk   ,\n        i_rst  : rst   ,\n        i_valid: valid ,\n        i_data : data  ,\n        o_ready: ready ,\n        o_tx   : tx    ,\n        o_valid: rvalid,\n        o_data : rdata ,\n    );\n\n    initial {\n        valid = 0;\n        data  = 0;\n        rst.assert();\n        clk.next(2);\n        // one frame = 10 bits × 8 clocks; the receiver reports in the stop bit\n        valid = 1;\n        data  = 8'hA5;\n        clk.next();\n        valid = 0;\n        clk.next(85);\n        $assert(rdata == 8'hA5, \"first byte\");\n        valid = 1;\n        data  = 8'h3C;\n        clk.next();\n        valid = 0;\n        clk.next(85);\n        $assert(rdata == 8'h3C, \"second byte\");\n        $finish();\n    }\n}\n"},{"name":"rvsoc_rom.veryl","src":"// generated by examples/sw/build.sh from rv32i_test.S -- do not edit\n// the same program with its data at 0x300, for TestRvSoc (examples/src/rvsoc.veryl)\nmodule RvTestProg (\n    i_addr: input  logic<32>,\n    o_inst: output logic<32>,\n) {\n    always_comb {\n        case i_addr[9:0] {\n            10'h000 : o_inst = 32'h30000f93; // addi x31,x0,768\n            10'h004 : o_inst = 32'h123450b7; // lui x1,0x12345\n            10'h008 : o_inst = 32'h67808093; // addi x1,x1,1656\n            10'h00c : o_inst = 32'h001fa023; // sw x1,0(x31)\n            10'h010 : o_inst = 32'h00000117; // auipc x2,0x0\n            10'h014 : o_inst = 32'h002fa223; // sw x2,4(x31)\n            10'h018 : o_inst = 32'hfffff137; // lui x2,0xfffff\n            10'h01c : o_inst = 32'h40c15113; // srai x2,x2,0xc\n            10'h020 : o_inst = 32'h002fa423; // sw x2,8(x31)\n            10'h024 : o_inst = 32'hff800193; // addi x3,x0,-8\n            10'h028 : o_inst = 32'h00300213; // addi x4,x0,3\n            10'h02c : o_inst = 32'h004182b3; // add x5,x3,x4\n            10'h030 : o_inst = 32'h005fa623; // sw x5,12(x31)\n            10'h034 : o_inst = 32'h403202b3; // sub x5,x4,x3\n            10'h038 : o_inst = 32'h005fa823; // sw x5,16(x31)\n            10'h03c : o_inst = 32'h004192b3; // sll x5,x3,x4\n            10'h040 : o_inst = 32'h005faa23;